//获取交流输入电网周期
void GetAcPeriod(void)
{
	switch(TriacState)
	{
		case 1:
			if(++TriacOutCnt < TriacDuty)
				break;
			TriacState ++;
			TriacOutCnt = 0;
			Moto_Pwm = 0;
			break;
		case 2:
			if(++TriacOutCnt < PULSE_MIN)
				break;
			TriacState = 0;
			TriacOutCnt = 0;
			Moto_Pwm = 1; 
			break;
		default:
			TriacState = 0;
			Moto_Pwm = 1; 
			TriacOutCnt = 0;
			break;
	}
	if((Zero == ZeroLastFlag) && (ZeroCnt < ZERO_CNT_LIMIT))
	{
		ZeroCnt++;
		return;
	}
	ZeroLastFlag = Zero;
	if(MotoRunFlag)
	{
		TriacState = 1;
		TriacOutCnt = 0;
		Moto_Pwm = 1; 
	}
	if((ZeroCnt<ZERO_CNT_MIN) || (ZeroCnt>ZERO_CNT_MAX))
	{
		ZeroCnt = 0;
		return;
	}
	
	AcTestTime += ZeroCnt;
	ZeroCnt = 0;
	if (AcCnt < 15)					//15
	{
		AcCnt++;
		return;
	}
	AcCnt = 0;
	AcTestTime >>=4;   //50Hz:2500; 60Hz:2000			//4
	if(AcTestTime>ZERO_CNT_50HZ)
	{
		Ac50HzFlag = 1;
		Limit_min = AC_50Hz-PULSE_MIN-LIMIT_MIN;
		Pid.Proportion = Kp_50Hz; // PID Kp
		Pid.Integral = Ki_50Hz;   // PID Ki
		Pid.Derivative = Kd_50Hz; // PID Kd
	}
	else
	{
		Ac50HzFlag = 0;
		Limit_min = AC_60Hz-PULSE_MIN-LIMIT_MIN;
		Pid.Proportion = Kp_60Hz; // PID Kp
		Pid.Integral = Ki_60Hz;   // PID Ki
		Pid.Derivative = Kd_60Hz; // PID Kd		
	}
	AcTestTime = 0;
	if(AcTestFlag)
		return;
	AcTestFlag = 1;
	OS_Trigger_Task(TaskKey);
}


void GetOption(void)
{
	uint8_t TmpOpt;

	TmpOpt = OTP1? 0x01:0x00;
	Delay_Ms(5);
  	if(TmpOpt != (OTP1? 0x01:0x00))
		TmpOpt = 0x01;
	if(TmpOpt)
	{
		GearRatioFlag = 1;
		Pid.MotoCounts = MotoCounts_65;
	}
	else
	{
		GearRatioFlag = 0;
		Pid.MotoCounts = MotoCounts_51;
	}
}



void HallScan(void)
{
	uint8_t HallVal;
    
	HallVal = HALL;
	if(HallVal != HallValLast)
  {
    HallValLast = HallVal;
    HallCnt = 0;
	}
	else
	{
		if(HallCnt > 1)
			return;
		if(++HallCnt == 1 )
			HallCount++;
	}
}

