//μ绺PID???
void Moto_Task(void)
{
	int TempDuty;
	
	if(MotoRunFlag == 0)
	{
		OS_Exit_Task();
		return;
	}
	OS_Wait_Timer(25);
	Pid.NextPoint = (uint8_t)Get_MotoCount();
	if((Pid.NextPoint < 1) || (Pid.NextPoint > (Pid.MotoCounts[GEAR_P]+20)))   //?˙1yμ????
	{
	  if(++ErrCnts > 200)
	  {
			ErrCnts = 0; 
			SET_SCR_OFF(MotoRunFlag);
			SET_LED(LED_FLASH);
	  }
	} 
	else
	  ErrCnts = 0; 
	Pid.Error = (int)Pid.SetPoint - (int)Pid.NextPoint;            // do PID
	Pid.IncPID_Val = (int)Pid.Proportion *(Pid.Error- Pid.Error1)                   // P
							+(int)Pid.Integral * Pid.Error*10/10                                    // I
							+(int)Pid.Derivative * (Pid.Error-2*Pid.Error1+Pid.Error2);              // D
	if(Pid.IncPID_Val < -ERR_MAX) Pid.IncPID_Val = -ERR_MAX;
	Pid.Error2=Pid.Error1;                          
	Pid.Error1=Pid.Error;
	TempDuty = TriacDuty;
	TempDuty -= Pid.IncPID_Val;
	if(TempDuty <  LIMIT_MAX)
		TempDuty =  LIMIT_MAX;
	else if(TempDuty >  Limit_min)
		TempDuty =   Limit_min;
	di();
	TriacDuty = TempDuty;
	ei();
	GetMotoOver();
	if(SetPointFlag)
		return;
	if(Pid.SetPoint > Pid.MotoCounts[MotoGear])
	{
			Pid.SetPoint--; 
			DelaySetCnt = 0;
	}
	else if(Pid.SetPoint < Pid.MotoCounts[MotoGear])
	{
		if(DelaySetCnt++ >1)
		{
			if(MotoGear==GEAR_P)
			{
				Pid.SetPoint +=3;
			}
			else
			{
				Pid.SetPoint++;
			}
			DelaySetCnt = 0;
		}
	}
	else
	{
		SetPointFlag = 1;
		DelaySetCnt = 0;
	}
}

void GetMotoOver(void)
{
	if(MotoGear > GEAR_3)
		return;
	if(TriacDuty < CurOverMax[Ac50HzFlag][GearRatioFlag][MotoGear-1])
	{
		OverDownCnt = 0;
		if(++OverUpCnt < MOTO_CUR_HIG_CNT)
			return;
		OverUpCnt = 0;
		SET_SCR_OFF(MotoRunFlag);
		SET_LED(LED_FLASH);
	}
	else
	{
		if(++OverDownCnt <  MOTO_CUR_LOW_CNT)
			return;
		OverDownCnt = 0;
		OverUpCnt = 0;
	}
}


void Key_Task(void)
{
	uint8_t i,KeyVal;
	uint8_t Key = 0xff;

	if(!bit_sdfastchk)
	{
//		OS_Wait_Timer(1); 		//5--5ms		
	}
	else
	{
		OS_Wait_Timer(20); 		 //20ms
	}
	
	KeyVal = P0&0x7f;
	KeyVal  |= GEAR6?0x80:0x00;
	for(i = 0; i<GEAR_N; i++)
	{
		if((KeyVal&Gear_Mask[i]) == 0)
		{
			Key = i;
			break;
		}
	}
	if(Key > 0x80)
		return;
	if(Key != MotoGear)
	{
		KeyCnt = 0;
		MotoGear = Key;
	}
	else
	{
		if((KeyCnt > KEY_PRESS)&&(bit_sdfastchk))
//		if(KeyCnt > KEY_PRESS)
			return;    
		if ((KeyCnt++ == KEY_PRESS)||(!bit_sdfastchk))
//		if (KeyCnt++ == KEY_PRESS)
		{
			if(MotoGear == 0)
			{
				bit_sdfastchk =1;
				ReturnZero = 1; 
				SET_LED (LED_FLASH);
				SET_SCR_OFF(MotoRunFlag);
				return;
			}
			else
			{
				SetPointFlag = 0;
				OverDownCnt = 0;
				OverUpCnt = 0;
				if(ReturnZero)
				{ 
					if(MotoGear == GEAR_P)
						Pid.SetPoint = 5;		//10	
					else
						Pid.SetPoint = 2;			//2	
					PidInit();
					SET_SCR_ON(MotoRunFlag);
					OS_Request_Task(TaskMoto);
					SET_LED(LED_ON);
					ReturnZero = 0;
				}
				else if(MotoRunFlag == 0)
					SET_LED(LED_FLASH);
			}
		}
	}
}

//设置档位灯
void Led_Task(void)
{
	OS_Wait_Timer(10);  //10ms
	switch(LedMode)
	{
		case LED_ON:
		case LED_OFF:
			Led_Pwm = LedMode?1:0;
			LedFlashCnt = 0;
			LedMode = 0xff;
			break;
		case LED_FLASH:
			if(LedFlashCnt)
				LedFlashCnt--;
			else
			{
				Led_Pwm = ~Led_Pwm;
				LedFlashCnt =LED_FLASH_CNT;
			}
			break;
	}
}






	